// Hitung Share of Voice (SoV) dari jumlah mention berita tiap brand
const cfg = $('Konfigurasi Brand').first().json;

const sources = [
  { role: 'Brand Kamu',   name: cfg.brand,       data: $('Serper - Brand').first().json },
  { role: 'Kompetitor 1', name: cfg.kompetitor1, data: $('Serper - Kompetitor 1').first().json },
  { role: 'Kompetitor 2', name: cfg.kompetitor2, data: $('Serper - Kompetitor 2').first().json },
];

const brands = sources.map(s => {
  const news = Array.isArray(s.data.news) ? s.data.news : [];
  const key = String(s.name).toLowerCase();

  // Mention = artikel yang judul/snippet-nya memuat nama brand
  const relevant = news.filter(n =>
    `${n.title || ''} ${n.snippet || ''}`.toLowerCase().includes(key)
  );

  const headlines = relevant.slice(0, 10).map((n, i) =>
    `${i + 1}. [${n.source || '-'}, ${n.date || '-'}] ${n.title || ''} - ${n.snippet || ''}`
  );

  return {
    role: s.role,
    name: s.name,
    totalResults: news.length,
    mentions: relevant.length,
    headlines,
  };
});

const totalMentions = brands.reduce((sum, b) => sum + b.mentions, 0);
brands.forEach(b => {
  b.sov = totalMentions > 0 ? Math.round((b.mentions / totalMentions) * 1000) / 10 : 0;
});

const processedAt = DateTime.now().setZone('Asia/Jakarta').toFormat("dd LLL yyyy, HH:mm 'WIB'");

const dataText = brands.map(b =>
  `=== ${b.role.toUpperCase()}: ${b.name} (${b.mentions} berita) ===\n` +
  (b.headlines.length ? b.headlines.join('\n') : 'Tidak ada berita relevan ditemukan.')
).join('\n\n');

const prompt =
`Kamu adalah analis reputasi merek. Analisis sentimen kumpulan berita terbaru berikut untuk 3 brand.
Berikan skor reputasi 1-10 untuk setiap brand (1 = sangat buruk, 10 = sangat baik) dan ringkasan eksekutif dalam Bahasa Indonesia.
Jika tidak ada berita untuk suatu brand, beri sentimen "Netral" dan skor 5 dengan alasan data tidak tersedia.

Jawab HANYA dengan JSON valid (tanpa markdown, tanpa teks lain) dengan skema:
{"brands":[{"name":"<nama brand persis seperti diberikan>","sentiment":"Positif|Netral|Negatif","reputation_score":<angka 1-10>,"reasoning":"<alasan singkat 1-2 kalimat>"}],"executive_summary":"<ringkasan eksekutif 3-4 kalimat>","recommendations":["<rekomendasi 1>","<rekomendasi 2>","<rekomendasi 3>"]}

DATA BERITA:
${dataText}`;

return [{ json: { brands, totalMentions, processedAt, prompt } }];

// Susun hasil analisis (SoV + AI) menjadi templat HTML laporan
const base = $('Hitung SoV').first().json;
const first = $input.first().json;

// Parse JSON dari output AI
let raw = String(first.text || first.output || '').replace(/```json|```/g, '').trim();
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
let ai = { brands: [], executive_summary: '', recommendations: [] };
try {
  ai = JSON.parse(raw.slice(s, e + 1));
} catch (err) {
  ai.executive_summary = 'Output AI tidak dapat dibaca sebagai JSON: ' + raw.slice(0, 300);
}

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const rows = base.brands.map((b, i) => {
  const a = (ai.brands || []).find(x => String(x.name).toLowerCase() === String(b.name).toLowerCase())
         || (ai.brands || [])[i] || {};
  return { ...b, sentiment: a.sentiment || '-', score: a.reputation_score ?? '-', reasoning: a.reasoning || '-' };
});

const leader = [...rows].sort((x, y) => y.sov - x.sov)[0];
const colorFor = s => ({ Positif: '#1E8E3E', Netral: '#B26A00', Negatif: '#C5221F' }[s] || '#555');

const tableRows = rows.map(r => `
  <tr>
    <td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.role)}</span></td>
    <td class="c">${r.mentions}</td>
    <td class="c">${r.sov}%</td>
    <td class="c" style="color:${colorFor(r.sentiment)};font-weight:bold">${esc(r.sentiment)}</td>
    <td class="c"><span class="score">${esc(r.score)}/10</span></td>
    <td>${esc(r.reasoning)}</td>
  </tr>`).join('');

const bars = rows.map(r => `
  <div class="barrow">
    <div class="barlabel">${esc(r.name)}</div>
    <div class="bartrack"><div class="barfill" style="width:${Math.max(r.sov, 2)}%"></div></div>
    <div class="barval">${r.sov}%</div>
  </div>`).join('');

const recs = (ai.recommendations || []).map(x => `<li>${esc(x)}</li>`).join('');

const html = `<!DOCTYPE html>
<html lang="id"><head><meta charset="UTF-8"><title>Laporan Competitor Monitoring</title>
<style>
  body{font-family:Arial,Helvetica,sans-serif;color:#222;margin:0;padding:32px;font-size:13px;line-height:1.5}
  .head{background:#1F4E79;color:#fff;padding:22px 26px;border-radius:8px}
  .head h1{margin:0 0 4px;font-size:22px}
  .head p{margin:0;font-size:12px;opacity:.9}
  h2{color:#1F4E79;font-size:16px;border-bottom:2px solid #1F4E79;padding-bottom:4px;margin-top:26px}
  .box{background:#EAF1F8;border-left:4px solid #1F4E79;padding:12px 16px;border-radius:4px}
  table{width:100%;border-collapse:collapse;margin-top:8px}
  th{background:#1F4E79;color:#fff;padding:8px;text-align:left;font-size:12px}
  td{border:1px solid #cfd8e3;padding:8px;vertical-align:top}
  tr:nth-child(even) td{background:#f6f9fc}
  .c{text-align:center}.muted{color:#777;font-size:11px}
  .score{background:#1F4E79;color:#fff;padding:3px 9px;border-radius:10px;font-weight:bold}
  .barrow{display:flex;align-items:center;margin:8px 0}
  .barlabel{width:150px;font-weight:bold}
  .bartrack{flex:1;background:#e3e9f0;height:16px;border-radius:8px;overflow:hidden}
  .barfill{background:#2E75B6;height:16px}
  .barval{width:60px;text-align:right;font-weight:bold}
  .foot{margin-top:30px;font-size:11px;color:#777;border-top:1px solid #ddd;padding-top:8px}
</style></head><body>
  <div class="head">
    <h1>Laporan Competitor Monitoring</h1>
    <p>${esc(rows.map(r => r.name).join(' vs '))} | Diproses: ${esc(base.processedAt)}</p>
  </div>

  <h2>Ringkasan Eksekutif</h2>
  <div class="box">
    <p><b>${esc(leader.name)}</b> memiliki Share of Voice tertinggi (${leader.sov}%) dari total ${base.totalMentions} mention berita.</p>
    <p>${esc(ai.executive_summary)}</p>
  </div>

  <h2>Share of Voice (SoV)</h2>
  ${bars}

  <h2>Tabel Perbandingan</h2>
  <table>
    <tr><th>Brand</th><th>Mention</th><th>SoV</th><th>Sentimen</th><th>Skor Reputasi</th><th>Alasan</th></tr>
    ${tableRows}
  </table>

  <h2>Rekomendasi</h2>
  <ol>${recs || '<li>-</li>'}</ol>

  <div class="foot">Sumber data: Serper API (Google News). Analisis sentimen: Gemini. processedAt: ${esc(base.processedAt)}</div>
</body></html>`;

return [{ json: { html, processedAt: base.processedAt } }];
